  this.modelsPromise=fetch('data/pointcloud-models.json').then(r=>{if(!r.ok)throw new Error();return r.json()}).catch(()=>({}));this.setFilter({matchedIds:new Set(artifacts.map(a=>a.id))});this.setTurning(this.turning);host.dataset.ready='true';
