  if(models[a.id])cloud=await this.modelCloud(models[a.id]);
  else {const img=new Image();img.src=a.displayImage;await img.decode();const canvas=document.createElement('canvas'),ratio=img.width/img.height;canvas.width=ratio>=1?240:Math.round(240*ratio);canvas.height=ratio>=1?Math.round(240/ratio):240;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);cloud=structuralVolume(ctx.getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height,COUNT,hash(a.id),volumeRecipe(a))}
